# dirty-L2 cost on the 21 MB read: harness-style zero flush vs a read-only flush, CUDA-event timing
import torch
from b200probe import cuda_kernel, harness_time
src=r'''
extern "C" __global__ void __launch_bounds__(256) rd4(const float4* __restrict__ b, float* __restrict__ out, long n32){
  long tid = blockIdx.x*256l+threadIdx.x; long stride=(long)gridDim.x*256; float v[4][8]; float acc=0.f;
  #pragma unroll
  for(int u=0;u<4;u++){ long i=tid+u*stride; if(i<n32){ const float* p=(const float*)(b+2*i);
    asm volatile("ld.global.nc.L1::no_allocate.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];" : "=f"(v[u][0]),"=f"(v[u][1]),"=f"(v[u][2]),"=f"(v[u][3]),"=f"(v[u][4]),"=f"(v[u][5]),"=f"(v[u][6]),"=f"(v[u][7]) : "l"(p)); } else { for(int j=0;j<8;j++) v[u][j]=0.f; } }
  #pragma unroll
  for(int u=0;u<4;u++) for(int j=0;j<8;j++) acc+=v[u][j];
  if(threadIdx.x==0) out[blockIdx.x]=acc;
}
'''
k=cuda_kernel(src,'rd4')
N,K=5120,2048
B=torch.randn(N,K,device='cuda',dtype=torch.float16)
n32=B.numel()*2//32; grid=(n32+1023)//1024
out=torch.zeros(1<<16,device='cuda')
big=torch.empty(252*1024*1024,dtype=torch.uint8,device='cuda')
def ev_time(fn, flush):
    ts=[]
    for _ in range(20):
        flush(); 
        s=torch.cuda.Event(enable_timing=True); e=torch.cuda.Event(enable_timing=True)
        s.record(); fn(); e.record(); torch.cuda.synchronize(); ts.append(s.elapsed_time(e)*1000)
    ts.sort(); return ts[len(ts)//2]
f=lambda: k((grid,),(256,),B,out,n32)
print("read 21MB after zero flush (events):", f"{ev_time(f, lambda: big.zero_()):.2f} us")
print("read 21MB after read-only flush (events):", f"{ev_time(f, lambda: big.sum()):.2f} us")
print("read 21MB harness_time:", f"{harness_time(lambda B,out: k((grid,),(256,),B,out,n32),[B],[out]):.2f} us")
e=cuda_kernel('extern "C" __global__ void e(float* o){ if(threadIdx.x==9999) o[0]=1; }','e')
print("empty after zero flush (events):", f"{ev_time(lambda: e((640,),(256,),out), lambda: big.zero_()):.2f} us")

import torch
from torch.profiler import profile, ProfilerActivity
N,K=5120,2048
B=torch.randn(N,K,device='cuda',dtype=torch.float16)
for M in [1,2,17,25,32,34,63,64,93,128,172,289,492,952]:
    A=torch.randn(M,K,device='cuda',dtype=torch.float16)
    C=torch.empty(M,N,device='cuda',dtype=torch.float16)
    for _ in range(3): torch.matmul(A,B.T,out=C)
    torch.cuda.synchronize()
    names={}
    with profile(activities=[ProfilerActivity.CUDA]) as p:
        for _ in range(5): torch.matmul(A,B.T,out=C)
        torch.cuda.synchronize()
    for ev in p.events():
        if ev.device_type.name=='CUDA': names[ev.name[:70]]=names.get(ev.name[:70],0)+1
    print(M, names)

